node -e "
import('child_process').then(async ({ spawn }) => {
  const edge = spawn('C:\\Program Files (x86)\\Microsoft\\Edge\\Application\\msedge.exe', [
    '--remote-debugging-port=9222',
    '--user-data-dir=' + process.env.TEMP + '\\edge_diag_' + Date.now(),
    '--headless=new',
    '--disable-gpu',
    'about:blank'
  ]);
  const sleep = ms => new Promise(r => setTimeout(r, ms));
  let wsUrl = null;
  for (let i = 0; i < 20; i++) {
    await sleep(500);
    try {
      const res = await fetch('http://localhost:9222/json');
      const tabs = await res.json();
      if (tabs?.[0]?.webSocketDebuggerUrl) { wsUrl = tabs[0].webSocketDebuggerUrl; break; }
    } catch(e){}
  }
  const ws = new WebSocket(wsUrl);
  let id = 1;
  const send = (method, params={}) => new Promise((resolve) => {
    const curId = id++;
    const handler = (msg) => {
      const d = JSON.parse(msg.data);
      if (d.id === curId) { ws.removeEventListener('message', handler); resolve(d.result); }
    };
    ws.addEventListener('message', handler);
    ws.send(JSON.stringify({ id: curId, method, params }));
  });
  await new Promise(r => ws.onopen = r);
  ws.addEventListener('message', (e) => {
    const d = JSON.parse(e.data);
    if (d.method === 'Runtime.exceptionThrown') {
      console.log('EXCEPTION:', JSON.stringify(d.params.exceptionDetails));
    }
    if (d.method === 'Runtime.consoleAPICalled') {
      console.log('CONSOLE:', d.params.type, d.params.args.map(a => a.value));
    }
  });
  await send('Page.enable');
  await send('Runtime.enable');
  await send('Page.navigate', { url: 'http://localhost:3000/login' });
  await sleep(1500);
  const res = await send('Runtime.evaluate', { expression: 'document.body.innerHTML', returnByValue: true });
  console.log('BODY HTML LENGTH:', res?.result?.value?.length);
  console.log('BODY HTML PREVIEW:', res?.result?.value?.substring(0, 300));
  ws.close();
  edge.kill();
  process.exit(0);
});
"

